<?php
$sql = "
CREATE TABLE IF NOT EXISTS " . TABLE_ZONES_TO_POST_CODE_FR . " (
    post_zone_id int NOT NULL AUTO_INCREMENT,
    zone_country_id int NOT NULL,
    zone_id int NOT NULL DEFAULT '0',
    post_code varchar(32) NOT NULL,
    zone_name varchar(32) NOT NULL,
    zone_city_name varchar(32) NOT NULL,
    zone_street_name varchar(32) DEFAULT '',
    PRIMARY KEY (post_zone_id),
    UNIQUE KEY post_code_2 (post_code,zone_city_name,zone_street_name),
    KEY post_code (post_code),
    KEY zone_id (zone_id),
    KEY zone_name (zone_name)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
";
$this->executeInstallerSql($sql);

$frenchcountries = ['FRA', 'GLP', 'GUF', 'PYF', 'MTQ', 'MYT', 'MCO', 'REU', 'NCL', 'SPM', 'WLF'];
for ($i = 0; $i < count($frenchcountries); $i++) {
    $sql = "SET @coid" . $i . " = (SELECT countries_id FROM countries WHERE countries_iso_code_3 = '" . $frenchcountries[$i] . "' ORDER BY countries_id DESC LIMIT 1);";
    $this->executeInstallerSql($sql);
}

